Trigger.TriggerText:
DECLARE v_start DATE; v_end DATE; v_status VARCHAR2(10);
BEGIN
  SELECT start_date, end_date, status INTO v_start, v_end, v_status
    FROM policies WHERE policy_no = :CLAIM.POLICY_NO;
  IF v_status <> 'ISSUED' OR :CLAIM.LOSS_DATE NOT BETWEEN v_start AND v_end THEN
    MESSAGE('Loss date is outside an issued policy period');
    RAISE FORM_TRIGGER_FAILURE;
  END IF;
END;

DECLARE v_dup NUMBER;
BEGIN
  SELECT COUNT(*) INTO v_dup FROM claims
   WHERE policy_no = :CLAIM.POLICY_NO AND loss_date = :CLAIM.LOSS_DATE;
  IF v_dup > 0 THEN
    IF SHOW_ALERT('ALR_DUPLICATE') = ALERT_BUTTON2 THEN RAISE FORM_TRIGGER_FAILURE; END IF;
  END IF;
  :CLAIM.HANDLER_GROUP := CASE WHEN :CLAIM.EST_AMOUNT > 10000 THEN 'SENIOR' ELSE 'STANDARD' END;
  SELECT 'CLM-' || LPAD(claim_seq.NEXTVAL, 7, '0') INTO :CLAIM.CLAIM_NO FROM dual;
END;
